const fs = require('fs');
const path = require('path');

const item = $input.first().json;
const useFace = item.use_face_reference;
const refImage = item.reference_image || 'avatar.jpg';
let publicImageUrl = null;

if (useFace) {
  const assetPath = path.join('D:/cyberx-website/Assets', refImage);
  if (fs.existsSync(assetPath)) {
    try {
      const fileBuffer = fs.readFileSync(assetPath);
      const blob = new Blob([fileBuffer], { type: 'image/jpeg' });
      const form = new FormData();
      form.append('file', blob, refImage);

      const res = await fetch('https://tmpfiles.org/api/v1/upload', {
        method: 'POST',
        body: form
      });
      const data = await res.json();
      if (data.data && data.data.url) {
        publicImageUrl = data.data.url.replace(/^http:\/\/tmpfiles\.org\/(\d+)\/(.*)$/i, 'https://tmpfiles.org/dl/$1/$2');
      }
    } catch (e) {
      // fallback if upload fails
    }
  }
}

return {
  json: {
    ...item,
    publicImageUrl: publicImageUrl
  }
};

