const geminiRes = $input.first().json;
const prev = $('Prepare Reference Image').first().json;

let prompt = '';
try {
  const text = geminiRes.candidates[0].content.parts[0].text;
  const parsed = JSON.parse(text);
  prompt = parsed.image_prompt;
} catch (e) {
  prompt = `A 3D cinematic promotional poster for CyberX ${prev.package_name}. Dark obsidian background (#0B0F19), glowing neon cyan (#00F0FF) and electric magenta (#FF007F) holographic cyber shield, 8k resolution, Unreal Engine 5 style.`;
}

return {
  json: {
    ...prev,
    craftedPrompt: prompt
  }
};

const response = $input.first().json;
const data = response.data;

if (data && data.state === 'success') {
  let imageUrl = null;
  try {
    const resultData = JSON.parse(data.resultJson);
    if (resultData.resultUrls && resultData.resultUrls.length > 0) {
      imageUrl = resultData.resultUrls[0];
    }
  } catch (e) {}

  if (!imageUrl && data.response && data.response.resultUrls) {
    imageUrl = data.response.resultUrls[0];
  }

  if (imageUrl) {
    return [{
      json: {
        imageUrl: imageUrl,
        taskId: data.taskId,
        status: 'completed',
        aspect_ratio: $('CyberX Campaign Inputs').first().json.aspect_ratio,
        package_name: $('CyberX Campaign Inputs').first().json.package_name
      }
    }];
  }
}

throw new Error(`Generation in progress or failed: ${data ? data.state : 'Unknown'}`);
